/* GENERATED by gen_hcon_vault.py -- models are generated.
   HUB_PROPOSAL : 7 feed(s) over 6 source view(s), 2 run(s): opus_health_legacy_v4, opus_health_v2
   LOADER SHAPE: ONE loader for this vault table; each run is a SEPARATE feed
   tagged by RECORD_SOURCE and SOURCE_RUN. RECORD_SOURCE is NEVER in the key.
   KEY FORM: md5(upper('HUB_PROPOSAL|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   REGISTRY RECONCILIATION, UNRESOLVED: unifying the hash form does NOT establish that the
   two runs' identifier spaces denote the same entities. 6 of the 14 shared hubs have ZERO
   business-key-column overlap between the runs. This hub is ONE KEY SPACE over the
   registries enumerated below; a false merge is unrecoverable after load.
     opus_health_legacy_v4    5 registry/registries: HUB_PROPOSAL_BK__BA_LEAD_NO, HUB_PROPOSAL_BK__HI_CONTROL_NUMBER, HUB_PROPOSAL_BK__KGC_PROPOSAL_NUMBER, HUB_PROPOSAL_BK__QUOTE_REF_NO, HUB_PROPOSAL_BK__REFERENCE_ID
     opus_health_v2           1 registry/registries: HUB_PROPOSAL_BK__SCRUTINY_NO
*/

with feeds as (
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__HI_CONTROL_NUMBER as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__hcp_pp_mem_dtls__5a3211af96') }}
    union all
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__SCRUTINY_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__enroll_pol_dtls__85ce324a4c') }}
    union all
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__KGC_PROPOSAL_NUMBER as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__gp_hospital_cash__d1205989f7') }}
    union all
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__REFERENCE_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__gp_hospital_cash__6763ba7a11') }}
    union all
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__QUOTE_REF_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__grp_hlt_dtls__ddbe03693e') }}
    union all
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__BA_LEAD_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__hdfc_sec_fhpp__160b74de40') }}
    union all
    select HUB_PROPOSAL_HK, HUB_PROPOSAL_BK__QUOTE_REF_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_proposal__hg_pol_dtls__cf8a5dad3f') }}
)

select
    HUB_PROPOSAL_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
from feeds
where HUB_PROPOSAL_HK is not null
group by HUB_PROPOSAL_HK, BUSINESS_KEY
